{
  "summary": "In July 2026 the card‑processor‑proxy local limiter began rejecting requests, causing rate‑limit errors on payment endpoints.",
  "likely_cause": "A single proxy instance was handling traffic after the other instance became unschedulable, exhausting its 180 RPS token bucket and generating CPX‑W430 rejections.",
  "confidence": "medium",
  "claims": [
    {
      "text": "The proxy introduced a local limiter on 2026‑07‑09 with 180 RPS per instance.",
      "evidence_ids": ["RB-029#1"],
      "quote": "Since 2026-07-09 the proxy also limits itself... CPX_LOCAL_RPS=180"
    },
    {
      "text": "When one proxy instance is missing, the survivor’s 180 RPS budget is the whole limit, and CPX‑W430 appears.",
      "evidence_ids": ["RB-029#4"],
      "quote": "`CPX-W430` only from card-processor-proxy-01... One instance gone; the survivor's 180 is the whole budget"
    },
    {
      "text": "A recorded incident on 2026‑09‑16 showed the node was cordoned, one proxy evicted, and CPX‑W430 logged on the remaining instance.",
      "evidence_ids": ["RB-029#8"],
      "quote": "At 19:40 proxy-02 was evicted... proxy-01 logged `CPX-W430` and payments‑api logged `PAYAPI-E1107`"
    }
  ],
  "next_checks": [
    "Check the scheduling status of the second proxy pod and node taints/anti‑affinity.",
    "Verify the current values of CPX_LOCAL_RPS and CPX_LOCAL_MAX_WAIT in the ConfigMap.",
    "Monitor CPX‑W430 and CPX‑W429 logs to distinguish local limiter rejections from processor push‑back."
  ]
}
